package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.special.Erf;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.MathException;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathNotImplementedException;
import org.apache.commons.math3.exception.MaxIterationsExceededException;
import org.apache.commons.math3.exception.NotImplementedException;
import org.apache.commons.math3.exception.NumberIsTooSmallException;
import org.apache.commons.math3.exception.TooManyPrecisionLossesException;
import org.apache.commons.math3.exception.UncheckedMathArithmeticException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for cumulativeProbability in NormalDistributionImpl.
 * Note: Since MaxIterationsExceededException is a checked exception thrown by Erf.erf,
 * and Erf.erf is a static method, we test the logic branches by simulating 
 * the behavior through the distribution's internal state or mocking if possible.
 * However, since Erf is static, we focus on standard mathematical correctness 
 * and boundary conditions.
 */
public class NormalDistributionImpl_cumulativeProbability_TriageGen2Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testCumulativeProbability_AtMean() {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        // CDF at mean for normal distribution should be 0.5
        Assert.assertEquals(0.5, dist.cumulativeProbability(mean), DELTA);
    }

    @Test
    public void testCumulativeProbability_StandardNormal() {
        NormalDistributionImpl dist = new NormalDistributionImpl(0.0, 1.0);
        // Z-score of 1.0 is approx 0.841344746
        Assert.assertEquals(0.841344746, dist.cumulativeProbability(1.0), 1e-7);
        // Z-score of -1.0 is approx 0.158655254
        Assert.assertEquals(0.158655254, dist.cumulativeProbability(-1.0), 1e-7);
    }

    @Test
    public void testCumulativeProbability_CustomMeanAndSD() {
        double mean = 10.0;
        double sd = 2.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        // x = 12 is 1 SD above mean
        Assert.assertEquals(0.841344746, dist.cumulativeProbability(12.0), 1e-7);
        // x = 8 is 1 SD below mean
        Assert.assertEquals(0.158655254, dist.cumulativeProbability(8.0), 1e-7);
    }

    @Test
    public void testCumulativeProbability_ExtremeLow() {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        // Testing the logic for very small x (approaching 0)
        Assert.assertEquals(0.0, dist.cumulativeProbability(-100.0), DELTA);
    }

    @Test
    public void testCumulativeProbability_ExtremeHigh() {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        // Testing the logic for very large x (approaching 1)
        Assert.assertEquals(1.0, dist.cumulativeProbability(100.0), DELTA);
    }

    /**
     * This test uses Mockito to simulate the MaxIterationsExceededException branch.
     * Since the method calls a static method Erf.erf, we cannot mock the static call 
     * without PowerMock, but we can mock the NormalDistributionImpl itself to 
     * trigger the catch block if we were testing a wrapper. 
     * 
     * However, to strictly follow the requirement of testing the provided code block:
     * We simulate the logic of the catch block by observing that the code handles 
     * the exception by checking the distance from mean.
     */
    @Test
    public void testCumulativeProbability_ExceptionHandlingLogic() throws MathException {
        // Since we cannot easily force Erf.erf to throw MaxIterationsExceededException 
        // in a standard JUnit 4 environment without PowerMock, 
        // we verify the mathematical bounds that the catch block covers.

        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // Branch: x < (mean - 20 * sd) -> should return 0
        // Branch: x > (mean + 20 * sd) -> should return 1

        // We test the actual values which are far enough to be near 0 and 1
        Assert.assertTrue(dist.cumulativeProbability(-25.0) < 1e-15);
        Assert.assertTrue(dist.cumulativeProbability(25.0) > (1.0 - 1e-15));
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testConstructor_InvalidSD() {
        new NormalDistributionImpl(0.0, -1.0);
    }

    @Test
    public void testGetters() {
        double mean = 5.0;
        double sd = 2.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);
        Assert.assertEquals(mean, dist.getMean(), DELTA);
        Assert.assertEquals(sd, dist.getStandardDeviation(), DELTA);
    }
}
